const {chromium}=require('/Users/dylanc/.npm/_npx/705bc6b22212b352/node_modules/playwright');
const fs=require('fs'),assert=require('assert'),crypto=require('crypto');
(async()=>{
  const browser=await chromium.launch({headless:true});
  const page=await browser.newPage();
  const source=fs.readFileSync('tools/talk.html','utf8');
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  let active=false, attempts=0, starts=0, stops=0;
  const pixel=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aV2kAAAAASUVORK5CYII=','base64');
  await page.route('http://127.0.0.1:8876/**',async route=>{
    const path=new URL(route.request().url()).pathname;
    if(path==='/')return route.fulfill({contentType:'text/html',body:source});
    if(path==='/start'){active=true;starts++;return route.fulfill({json:{}});}
    if(path==='/stop'){active=false;stops++;return route.fulfill({json:{}});}
    if(path==='/status')return route.fulfill({json:{phase:active?'Listening':'Idle',active,view_ready:active,error:''}});
    if(path==='/robot')return route.fulfill({json:{status:'Listening',settings:{},control:{targets:[]},transcript:[],evidence:{}}});
    if(path==='/camera'){
      attempts++;
      if(attempts===2)return route.abort('connectionrefused');
      if(attempts<4)return route.fulfill({status:503,body:'View unavailable'});
      return route.fulfill({contentType:'image/png',body:pixel});
    }
    return route.fulfill({status:404,body:''});
  });
  const started=Date.now();
  try{
    await page.goto('http://127.0.0.1:8876');
    await page.locator('#start').click();
    await page.waitForFunction(()=>document.getElementById('camera').naturalWidth>0,{},{timeout:3000});
    assert.equal(attempts,4);assert.equal(starts,1);
    assert(await page.locator('#camera').isVisible());
    await page.waitForTimeout(900);assert.equal(attempts,4,'healthy image is not repeatedly reopened');
    await page.locator('#stop').click();
    await page.waitForTimeout(700);assert.equal(attempts,4);assert.equal(stops,1);
    assert(!(await page.locator('#camera').isVisible()));assert.equal(errors.length,0);
    const result={what:'first camera request fails, followed by abort and failure; recover without reload',
      complete:true,machine:'Mac headless Chromium',requests:attempts,page_loads:1,starts,stops,
      html_sha256:crypto.createHash('sha256').update(source).digest('hex'),elapsed_ms:Date.now()-started,
      command:'node build/first-start/browser.cjs'};
    fs.writeFileSync('build/first-start/browser-result.json',JSON.stringify(result,null,2)+'\n');
    console.log(JSON.stringify(result));
  }finally{await browser.close();}
})().catch(e=>{console.error(e.message);process.exitCode=1;});
